const e=JSON.parse("[{\"id\": \"2nde-it-01\", \"grade\": \"2nde\", \"subject\": \"italien\", \"chapter\": \"L'imparfait\", \"difficulty\": 2, \"format\": \"mcq\", \"prompt\": \"Complète à l'imparfait : « Da bambino, io … molto timido. » (essere)\", \"choices\": [\"ero\", \"sono\", \"sarò\", \"fui\"], \"answer\": \"ero\", \"explanation\": \"Essere à l'imparfait : ero, eri, era, eravamo, eravate, erano.\"}, {\"id\": \"2nde-it-02\", \"grade\": \"2nde\", \"subject\": \"italien\", \"chapter\": \"Le futur\", \"difficulty\": 2, \"format\": \"short\", \"strict\": true, \"prompt\": \"Conjugue andare au futur, 1re personne du singulier : io …\", \"answer\": \"andrò\", \"explanation\": \"Andare au futur : andrò, andrai, andrà, andremo, andrete, andranno (accent sur le ò final).\"}, {\"id\": \"2nde-it-03\", \"grade\": \"2nde\", \"subject\": \"italien\", \"chapter\": \"Le comparatif\", \"difficulty\": 2, \"format\": \"mcq\", \"prompt\": \"Complète : « Roma è … grande … Firenze. »\", \"choices\": [\"più / di\", \"più / che\", \"tanto / di\", \"meno / come\"], \"answer\": \"più / di\", \"explanation\": \"Comparatif de supériorité : più + adjectif + di (devant un nom ou un pronom).\"}, {\"id\": \"2nde-it-04\", \"grade\": \"2nde\", \"subject\": \"italien\", \"chapter\": \"Civilisation\", \"difficulty\": 2, \"format\": \"mcq\", \"prompt\": \"Qui a écrit la « Divina Commedia » ?\", \"choices\": [\"Dante Alighieri\", \"Pétrarque\", \"Boccace\", \"Machiavel\"], \"answer\": \"Dante Alighieri\", \"explanation\": \"Dante, né à Florence en 1265, écrit la Divine Comédie au début du XIVe siècle : Enfer, Purgatoire, Paradis.\"}, {\"id\": \"2nde-it-05\", \"grade\": \"2nde\", \"subject\": \"italien\", \"chapter\": \"Civilisation\", \"difficulty\": 1, \"format\": \"mcq\", \"prompt\": \"Quelle est la capitale de l'Italie ?\", \"choices\": [\"Rome\", \"Milan\", \"Florence\", \"Naples\"], \"answer\": \"Rome\", \"explanation\": \"Rome est la capitale de l'Italie depuis 1871.\"}, {\"id\": \"2nde-it-06\", \"grade\": \"2nde\", \"subject\": \"italien\", \"chapter\": \"Vocabulaire\", \"difficulty\": 2, \"format\": \"match\", \"prompt\": \"Attention aux pièges : associe chaque mot italien à son vrai sens.\", \"pairs\": [[\"caldo\", \"chaud\"], [\"la tazza\", \"la tasse\"], [\"la fermata\", \"l'arrêt (de bus)\"], [\"guardare\", \"regarder\"]], \"explanation\": \"« caldo » veut dire chaud (et non froid) ; « la fermata » est l'arrêt de bus ; « guardare » signifie regarder.\"}, {\"id\": \"2nde-it-07\", \"grade\": \"2nde\", \"subject\": \"italien\", \"chapter\": \"L'imparfait\", \"difficulty\": 3, \"format\": \"fix\", \"prompt\": \"Trouve le mot mal écrit.\", \"sentence\": \"Quando ero piccolo, giocavo spesso e mia sorella {leggevi|leggeva} molto.\", \"explanation\": \"Avec « mia sorella » (3e personne), l'imparfait de leggere est « leggeva ».\"}, {\"id\": \"1re-it-01\", \"grade\": \"1re\", \"subject\": \"italien\", \"chapter\": \"Le subjonctif présent\", \"difficulty\": 2, \"format\": \"mcq\", \"prompt\": \"Complète : « Penso che lui … stanco. » (essere)\", \"choices\": [\"sia\", \"è\", \"fosse\", \"sarà\"], \"answer\": \"sia\", \"explanation\": \"Après un verbe d'opinion (penso che), l'italien emploie le subjonctif : che lui sia.\"}, {\"id\": \"1re-it-02\", \"grade\": \"1re\", \"subject\": \"italien\", \"chapter\": \"Le subjonctif présent\", \"difficulty\": 3, \"format\": \"short\", \"strict\": true, \"prompt\": \"Complète au subjonctif présent : « Spero che tu … (avere) ragione. »\", \"answer\": \"abbia\", \"explanation\": \"Avere au subjonctif présent : che io abbia, che tu abbia, che lui abbia…\"}, {\"id\": \"1re-it-03\", \"grade\": \"1re\", \"subject\": \"italien\", \"chapter\": \"Le conditionnel\", \"difficulty\": 2, \"format\": \"mcq\", \"prompt\": \"Pour commander poliment : « … un caffè, per favore. »\", \"choices\": [\"Vorrei\", \"Voglio\", \"Volevo\", \"Vorrò\"], \"answer\": \"Vorrei\", \"explanation\": \"« Vorrei » (conditionnel de volere) = je voudrais : c'est la forme polie.\"}, {\"id\": \"1re-it-04\", \"grade\": \"1re\", \"subject\": \"italien\", \"chapter\": \"Civilisation\", \"difficulty\": 2, \"format\": \"match\", \"prompt\": \"Associe chaque artiste de la Renaissance à l'une de ses œuvres.\", \"pairs\": [[\"Léonard de Vinci\", \"La Joconde\"], [\"Michel-Ange\", \"La voûte de la chapelle Sixtine\"], [\"Botticelli\", \"La Naissance de Vénus\"], [\"Raphaël\", \"L'École d'Athènes\"]], \"explanation\": \"Quatre grands noms de la Renaissance italienne (XVe-XVIe siècles).\"}, {\"id\": \"1re-it-05\", \"grade\": \"1re\", \"subject\": \"italien\", \"chapter\": \"Civilisation\", \"difficulty\": 2, \"format\": \"mcq\", \"prompt\": \"Quelle famille a dominé Florence et soutenu les artistes de la Renaissance ?\", \"choices\": [\"les Médicis\", \"les Borgia\", \"les Sforza\", \"les Savoie\"], \"answer\": \"les Médicis\", \"explanation\": \"Les Médicis, banquiers, gouvernent Florence et deviennent de grands mécènes (Laurent le Magnifique).\"}, {\"id\": \"1re-it-06\", \"grade\": \"1re\", \"subject\": \"italien\", \"chapter\": \"Les pronoms\", \"difficulty\": 3, \"format\": \"mcq\", \"prompt\": \"Remplace le complément : « Do il libro a Marco » → « … do. »\", \"choices\": [\"Glielo\", \"Gli lo\", \"Lo gli\", \"Le lo\"], \"answer\": \"Glielo\", \"explanation\": \"gli (à lui) + lo (le) forment le pronom groupé « glielo » : glielo do.\"}, {\"id\": \"term-it-01\", \"grade\": \"term\", \"subject\": \"italien\", \"chapter\": \"La phrase hypothétique\", \"difficulty\": 3, \"format\": \"mcq\", \"prompt\": \"Complète : « Se … tempo, viaggerei di più. » (avere)\", \"choices\": [\"avessi\", \"avrei\", \"ho\", \"avevo\"], \"answer\": \"avessi\", \"explanation\": \"Hypothèse irréelle : se + subjonctif imparfait (avessi) + conditionnel (viaggerei).\"}, {\"id\": \"term-it-02\", \"grade\": \"term\", \"subject\": \"italien\", \"chapter\": \"Le passé simple\", \"difficulty\": 3, \"format\": \"mcq\", \"prompt\": \"« Dante nacque a Firenze nel 1265. » Quel est l'infinitif de « nacque » ?\", \"choices\": [\"nascere\", \"nascondere\", \"nuotare\", \"notare\"], \"answer\": \"nascere\", \"explanation\": \"« nacque » est le passato remoto de nascere (naître), temps du récit historique.\"}, {\"id\": \"term-it-03\", \"grade\": \"term\", \"subject\": \"italien\", \"chapter\": \"Histoire\", \"difficulty\": 2, \"format\": \"number\", \"prompt\": \"En quelle année le royaume d'Italie est-il proclamé (unité italienne) ?\", \"answer\": \"1861\", \"explanation\": \"Le 17 mars 1861, Victor-Emmanuel II est proclamé roi d'Italie. Rome devient capitale en 1871.\"}, {\"id\": \"term-it-04\", \"grade\": \"term\", \"subject\": \"italien\", \"chapter\": \"Histoire\", \"difficulty\": 2, \"format\": \"order\", \"prompt\": \"Range ces étapes de l'histoire italienne de la plus ancienne à la plus récente.\", \"items\": [\"Proclamation du royaume d'Italie\", \"Rome devient capitale\", \"Marche sur Rome de Mussolini\", \"Référendum créant la République\"], \"explanation\": \"1861, 1871, 1922, 1946.\"}, {\"id\": \"term-it-05\", \"grade\": \"term\", \"subject\": \"italien\", \"chapter\": \"Littérature\", \"difficulty\": 3, \"format\": \"mcq\", \"prompt\": \"Qui a écrit le roman « I promessi sposi » (Les Fiancés) ?\", \"choices\": [\"Alessandro Manzoni\", \"Italo Calvino\", \"Umberto Eco\", \"Primo Levi\"], \"answer\": \"Alessandro Manzoni\", \"explanation\": \"Manzoni publie « I promessi sposi » au XIXe siècle (version définitive en 1840-1842) ; c'est un roman fondateur de la langue italienne moderne.\"}, {\"id\": \"term-it-06\", \"grade\": \"term\", \"subject\": \"italien\", \"chapter\": \"Littérature\", \"difficulty\": 2, \"format\": \"mcq\", \"prompt\": \"Quel écrivain, rescapé d'Auschwitz, a écrit « Se questo è un uomo » ?\", \"choices\": [\"Primo Levi\", \"Alberto Moravia\", \"Cesare Pavese\", \"Luigi Pirandello\"], \"answer\": \"Primo Levi\", \"explanation\": \"Primo Levi témoigne de sa déportation dans « Si c'est un homme » (1947).\"}]"),a={questions:e};export{a as default,e as questions};
